{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.zouk_billable_report_v3 AS WITH WIP_Latest AS ( SELECT LOWER(CAST(Item_id AS STRING)) AS SKU, MAX(SAFE.PARSE_DATE(\'%Y-%m-%d\', Data_Updated_Date)) AS Latest_Date FROM MapleMonk.Zouk_Zouk_S3_TranZact_WIP WHERE Item_id IS NOT NULL GROUP BY SKU ), WIP_Final AS ( SELECT LOWER(CAST(w.Item_id AS STRING)) AS SKU, SUM( SAFE_CAST(w.Estimated_Quantity AS INT64) - SAFE_CAST(w.Quantity_Produced AS INT64) ) AS WIP FROM MapleMonk.Zouk_Zouk_S3_TranZact_WIP w JOIN WIP_Latest l ON LOWER(CAST(w.Item_id AS STRING)) = l.SKU AND SAFE.PARSE_DATE(\'%Y-%m-%d\', w.Data_Updated_Date) = l.Latest_Date GROUP BY SKU ), Inventory_Latest AS ( SELECT LOWER(SKU) AS SKU, Available_Inventory, ROW_NUMBER() OVER ( PARTITION BY LOWER(SKU) ORDER BY DATA_FETCH_DATE DESC ) AS rn FROM `MapleMonk.ZOUK_INVENTORY_FACT_ITEMS` ), Inventory_Final AS ( SELECT SKU, SUM(Available_Inventory) AS Available_Inventory FROM Inventory_Latest WHERE rn = 1 GROUP BY SKU ), B2B_Pivot AS ( SELECT cast(nullif(Order_Date_as_dd_mm_yyyy_hh_MM_ss,\"\") as datetime) as Order_Date, nullif(Invoice_date,\"\") as Invoice_Date, invoice_code, Sale_Order_Code AS Order_id, Display_Order_Code as Reference_Code, UPPER(Channel_Name) AS Marketplace, LOWER(Item_SKU_Code) AS SKU, UPPER(Facility) AS Facility, SUM(SAFE_CAST(NULLIF(Unallocated_Quantity, \'\') AS FLOAT64)) AS Unallocated_Qty, SUM(SAFE_CAST(NULLIF(Allocated_Quantity, \'\') AS FLOAT64)) AS Allocated_Qty, SUM(SAFE_CAST(NULLIF(In_Process_Quantity, \'\') AS FLOAT64)) AS In_Process_Qty FROM `MapleMonk.New_Zouk_get_b2b_sale_orders` GROUP BY 1,2,3,4,5,6,7,8 ), Combined AS ( SELECT p.Order_Date, p.Invoice_Date, p.Invoice_Code, p.Order_Id, p.Reference_Code, p.Marketplace, p.SKU, p.Facility, COALESCE(p.Unallocated_Qty, 0) AS Unallocated, COALESCE(p.Allocated_Qty, 0) AS Allocated_Qty, COALESCE(p.In_Process_Qty, 0) AS In_Process_Qty, COALESCE(inv.Available_Inventory, 0) AS Total_Inventory, COALESCE(wip.WIP, 0) AS Total_WIP, fsm.brand AS Brand, fsm.commonsku AS Common_SKU, fsm.collection AS Collection, fsm.category AS Product_Category, fsm.print AS Print, fsm.Product_Type AS Product_Type, UPPER(mm.Marketplace_segments) Marketplace_Segment, upper(mm.Final_Marketplace) Final_Marketplace, UPPER(mm.Channel) AS Channel, UPPER(mm.Grouped_Channel) AS Grouped_Channel, ROW_NUMBER() OVER ( PARTITION BY p.SKU ORDER BY p.Marketplace ) AS row_within_sku FROM B2B_Pivot p LEFT JOIN Inventory_Final inv ON p.SKU = inv.SKU LEFT JOIN WIP_Final wip ON p.SKU = wip.SKU LEFT JOIN ( SELECT * FROM `MapleMonk.FINAL_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(commonsku) ORDER BY 1) = 1 ) fsm ON p.SKU = LOWER(fsm.commonsku) LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from `MapleMonk.Zouk_db_New_Marketplace_Mapping` ) where rw =1 ) mm ON trim(UPPER(REPLACE(p.Marketplace,\" \",\"_\"))) = trim(Upper(mm.marketplace)) ), Pass1 AS ( SELECT *, Unallocated + Allocated_Qty AS Open_PO, Allocated_Qty + In_Process_Qty AS Allocated, COALESCE( SUM(Unallocated) OVER ( PARTITION BY SKU ORDER BY row_within_sku ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0) AS cum_unallocated_above FROM Combined ), Pass2 AS ( SELECT *, LEAST( GREATEST(Total_Inventory - cum_unallocated_above, 0), Unallocated ) AS Fulfillable FROM Pass1 ), Pass3 AS ( SELECT *, Unallocated - Fulfillable AS Unfulfillable, COALESCE( SUM(Fulfillable) OVER ( PARTITION BY SKU ORDER BY row_within_sku ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0) AS cum_fulfillable_above FROM Pass2 ), Pass4 AS ( SELECT *, LEAST( GREATEST(Total_WIP - cum_fulfillable_above, 0), Unfulfillable ) AS WIP_Used FROM Pass3 ) SELECT Order_Date, Invoice_Date, Invoice_Code, Order_Id, Reference_Code, DATE_DIFF(Current_date(),date(Order_Date),DAY) AS PO_Age, Marketplace, SKU, Facility, Brand, Common_SKU, Collection, Product_Category, Print, Product_Type, Marketplace_Segment, Channel, Grouped_Channel, Final_Marketplace, CAST(Open_PO AS INT64) AS Open_PO, CAST(Allocated AS INT64) AS Allocated, CAST(Unallocated AS INT64) AS Unallocated, CAST(Fulfillable AS INT64) AS Fulfillable, CAST(Unfulfillable AS INT64) AS Unfulfillable, CAST(WIP_Used AS INT64) AS WIP, CAST(Unfulfillable - WIP_Used AS INT64) AS Unfulfillable_After_WIP FROM Pass4 ORDER BY SKU, Marketplace",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            